using System;
using UnityEngine;

namespace VerdantSiege.Audio
{
    /// <summary>
    /// All game audio in one asset. Per-sfx arrays are indexed by (int)<see cref="Sfx"/>.
    /// Generated by Tools/Verdant Siege/Generate Audio; any clip can be swapped by hand afterwards.
    /// Getters tolerate missing or short arrays (new enum entries simply fall back to defaults).
    /// </summary>
    [CreateAssetMenu(menuName = "Verdant Siege/Audio Library", fileName = "AudioLibrary")]
    public sealed class AudioLibrary : ScriptableObject
    {
        public const float DefaultVolume = 1f;
        public const int DefaultMaxVoices = 3;
        public const float DefaultMinInterval = 0f;

        /// <summary>Number of <see cref="Sfx"/> values (cached; no per-call allocation).</summary>
        public static readonly int SfxCount = Enum.GetValues(typeof(Sfx)).Length;

        [Header("One-shots (indexed by Sfx)")]
        public AudioClip[] sfx = new AudioClip[0];
        public float[] sfxVolume = new float[0];
        [Tooltip("Maximum simultaneous voices of the same Sfx; the oldest is restarted when exceeded.")]
        public int[] maxVoices = new int[0];
        [Tooltip("Minimum seconds (unscaled) between two plays of the same Sfx; extra requests are dropped.")]
        public float[] minInterval = new float[0];

        [Header("Music & ambience")]
        public AudioClip menuMusic;
        public AudioClip battleMusic;
        [Tooltip("Optional; may be null.")]
        public AudioClip victorySting;
        public AudioClip ambienceLoop;

        [Header("Track gains")]
        [Range(0f, 1f)] public float menuMusicVolume = 0.7f;
        [Range(0f, 1f)] public float battleMusicVolume = 0.6f;
        [Range(0f, 1f)] public float victoryStingVolume = 0.9f;
        [Range(0f, 1f)] public float ambienceVolume = 0.5f;

        public AudioClip GetClip(Sfx s)
        {
            int i = (int)s;
            return sfx != null && i >= 0 && i < sfx.Length ? sfx[i] : null;
        }

        public float GetVolume(Sfx s)
        {
            int i = (int)s;
            return sfxVolume != null && i >= 0 && i < sfxVolume.Length ? Mathf.Max(0f, sfxVolume[i]) : DefaultVolume;
        }

        public int GetMaxVoices(Sfx s)
        {
            int i = (int)s;
            int v = maxVoices != null && i >= 0 && i < maxVoices.Length ? maxVoices[i] : DefaultMaxVoices;
            return v < 1 ? 1 : v;
        }

        public float GetMinInterval(Sfx s)
        {
            int i = (int)s;
            return minInterval != null && i >= 0 && i < minInterval.Length ? Mathf.Max(0f, minInterval[i]) : DefaultMinInterval;
        }

        /// <summary>Per-track gain for a music/ambience clip from this library (1 for unknown clips).</summary>
        public float GetMusicGain(AudioClip clip)
        {
            if (clip == null) return 1f;
            if (clip == battleMusic) return battleMusicVolume;
            if (clip == menuMusic) return menuMusicVolume;
            if (clip == ambienceLoop) return ambienceVolume;
            if (clip == victorySting) return victoryStingVolume;
            return 1f;
        }

        /// <summary>Grows/shrinks the per-sfx arrays to <see cref="SfxCount"/>, keeping existing values.</summary>
        public void EnsureArraySizes()
        {
            int n = SfxCount;
            if (sfx == null || sfx.Length != n) Array.Resize(ref sfx, n);
            sfxVolume = Resize(sfxVolume, n, DefaultVolume);
            maxVoices = Resize(maxVoices, n, DefaultMaxVoices);
            minInterval = Resize(minInterval, n, DefaultMinInterval);
        }

        private static T[] Resize<T>(T[] arr, int n, T fill)
        {
            int old = arr == null ? 0 : arr.Length;
            if (old == n) return arr;
            var result = new T[n];
            for (int i = 0; i < n; i++) result[i] = i < old ? arr[i] : fill;
            return result;
        }

        private void OnValidate()
        {
            EnsureArraySizes();
        }
    }
}
